import React from "react";
import { BrowserRouter as Router, Routes, Route } from "react-router-dom";
import Navbar from "./components/Navbar";
import AdminDashboard from "./pages/AdminDashboard";
import UserDashboard from "./pages/UserDashboard";
import Analytics from "./pages/Analytics";
import Logs from "./pages/Logs";

function App() {
  // For demo, you can toggle role: "admin" or "user"
  const role = "admin"; // change to "user" to test

  return (
    <Router>
      <Navbar role={role} />
      <Routes>
        <Route path="/" element={role === "admin" ? <AdminDashboard /> : <UserDashboard />} />
        {role === "admin" && <Route path="/analytics" element={<Analytics />} />}
        {role === "admin" && <Route path="/logs" element={<Logs />} />}
      </Routes>
    </Router>
  );
}

export default App;
